<?php
$base='../';$tituloPagina='Ventas';require_once __DIR__.'/../php/conexion.php';require_once __DIR__.'/../php/auth.php';require_once __DIR__.'/../php/util.php';requerirAdministrador();
$ventas=$conexion->query("SELECT v.id_venta,v.fecha,v.total,u.nombre,u.correo,GROUP_CONCAT(CONCAT(d.cantidad,' x ',p.nombre_producto) SEPARATOR ' · ') productos FROM ventas v JOIN usuarios u ON u.id_usuario=v.id_usuario JOIN detalle_venta d ON d.id_venta=v.id_venta JOIN productos p ON p.id_producto=d.id_producto GROUP BY v.id_venta,v.fecha,v.total,u.nombre,u.correo ORDER BY v.fecha DESC");require_once __DIR__.'/../php/encabezado.php';
?><main class="container py-5"><p class="eyebrow">REPORTES</p><h1>Ventas realizadas</h1><div class="table-responsive mt-4"><table class="table table-hover"><thead><tr><th>Venta</th><th>Fecha</th><th>Cliente</th><th>Detalle</th><th>Total</th></tr></thead><tbody><?php while($v=$ventas->fetch_assoc()): ?><tr><td>#<?php echo $v['id_venta']; ?></td><td><?php echo e($v['fecha']); ?></td><td><?php echo e($v['nombre']); ?><br><small><?php echo e($v['correo']); ?></small></td><td><?php echo e($v['productos']); ?></td><td>$<?php echo number_format($v['total'],2); ?></td></tr><?php endwhile; ?></tbody></table></div></main><?php require_once __DIR__.'/../php/pie.php'; ?>
